;---------------------------------------------------------------------------
; reciprocals: 65536/n (n=1 saturates to $FFFF), n = 0..95.
;---------------------------------------------------------------------------
recip_lo:                               ; 65536/n, n = 0..95 (0 -> 0, 1 -> $FFFF)
        .repeat 96, N
        .if N = 0
        .byte   0
        .elseif N = 1
        .byte   $FF
        .else
        .byte   <(65536 / N)
        .endif
        .endrepeat
recip_hi:
        .repeat 96, N
        .if N = 0
        .byte   0
        .elseif N = 1
        .byte   $FF
        .else
        .byte   >(65536 / N)
        .endif
        .endrepeat

